 w.repeatCount, w.repeatFingerprint = 0, ""
 return nil
 }
 anon := pass
 anon.N = 0
 _ = anon
 sum := sha256.Sum256([]byte(strings.Join([]string{stage, strings.Join(pass.Failing, "\x00"), ""}, "\x1f")))
 fingerprint := hex.EncodeToString(sum[:])
 if w.repeatFingerprint == fingerprint { w.repeatCount++ } else { w.repeatCount, w.repeatFingerprint = 1, fingerprint }
 if w.repeatCount < 4 { return nil }
 b.Run.Event(map[string]any{"event":"no_progress", "fingerprint":fingerprint, "count":w.repeatCount, "failing":core.NonNil(pass.Failing)})
 message := "same failure persisted for 4 consecutive clean red passes: " + strings.Join(pass.Failing, ", ")
 if items := missingAcceptanceItems(pass); len(items) > 0 { message += "; " + strings.Join(items, ", ") }
 return sys.Fail("candidate", "no_progress", message, 1)
}
